INSERT INTO system_voices (system_id,voice_name,tts_voice_ids,hooks,ctas) VALUES ('dnd5e','friendly_vet',ARRAY['alloy','ash'],ARRAY['Old-school kit check: {name}.','Dungeon kit spotlight: {name}.'],ARRAY['DMs: drop one in the dungeon and watch the party start thinking like engineers.','Players: buy this before your next shiny weapon.']);
INSERT INTO system_voices (system_id,voice_name,tts_voice_ids,hooks,ctas) VALUES ('dnd5e','gritty_dm',ARRAY['onyx','echo'],ARRAY['In the dark, rope beats steel: {name}.','This is how you move the world: {name}.'],ARRAY['DMs: make the environment heavy. Let tools matter.','Players: win fights by winning terrain first.']);
INSERT INTO system_voices (system_id,voice_name,tts_voice_ids,hooks,ctas) VALUES ('dnd5e','rules_lawyer',ARRAY['sage','ash'],ARRAY['Mechanics moment: {name}.','Rules-forward pick: {name}.'],ARRAY['If you want ‘smart play’, reward prep like this.','Track time, anchors, and positioning—this is where it earns its keep.']);
INSERT INTO system_voices (system_id,voice_name,tts_voice_ids,hooks,ctas) VALUES ('shadowdark','grim_warden',NULL,ARRAY['In the dark, {name} matters.','Hard lesson: {name}.'],ARRAY['DMs: reward caution and punish noise.','Players: win with prep, not bravado.']);
INSERT INTO system_voices (system_id,voice_name,tts_voice_ids,hooks,ctas) VALUES ('shadowdark','strict_referee',NULL,ARRAY['Ruling check: {name}.','Table call: {name}.'],ARRAY['Keep rulings fast, clear, and consistent.','Call intent first, then roll.']);
INSERT INTO system_voices (system_id,voice_name,tts_voice_ids,hooks,ctas) VALUES ('shadowdark','torchbearer_ref',NULL,ARRAY['Torchlight briefing: {name}.','Dungeon brief: {name}.'],ARRAY['DMs: put pressure on time, light, and noise.','Players: solve for survival before style points.']);
INSERT INTO system_voice_category_lines (system_id,voice_name,category,hooks,ctas) VALUES ('dnd5e','friendly_vet','monster_tactic',ARRAY['Monster check: {name}.','Table troublemaker: {name}.'],ARRAY['DMs: run it like it wants to win, not like it wants to die politely.','Players: solve the monster, don’t just swing at it.']);
INSERT INTO system_voice_category_lines (system_id,voice_name,category,hooks,ctas) VALUES ('dnd5e','friendly_vet','spell_use_case',ARRAY['Spell play: {name}.','Pocket magic: {name}.'],ARRAY['DMs: let clever casting change the scene.','Players: don’t cast it—*aim* it.']);
INSERT INTO system_voice_category_lines (system_id,voice_name,category,hooks,ctas) VALUES ('dnd5e','gritty_dm','monster_tactic',ARRAY['In the dark, {name} is a problem.','Tonight’s lesson: {name}.'],ARRAY['DMs: hit hard, then disengage—predators don’t trade blows.','Players: control space or bleed for it.']);
INSERT INTO system_voice_category_lines (system_id,voice_name,category,hooks,ctas) VALUES ('dnd5e','gritty_dm','spell_use_case',ARRAY['Magic with teeth: {name}.','When it matters: {name}.'],ARRAY['DMs: make magic costly, not pointless.','Players: spend the slot when it swings the fight.']);
INSERT INTO system_voice_category_lines (system_id,voice_name,category,hooks,ctas) VALUES ('dnd5e','rules_lawyer','monster_tactic',ARRAY['Statblock truth: {name}.','Tactics note: {name}.'],ARRAY['DMs: reward good positioning; punish sloppy clustering.','Players: deny advantage, deny actions, deny turns.']);
INSERT INTO system_voice_category_lines (system_id,voice_name,category,hooks,ctas) VALUES ('dnd5e','rules_lawyer','spell_use_case',ARRAY['Spell timing note: {name}.','Rules nugget: {name}.'],ARRAY['DMs: enforce components and concentration—spells get sharper.','Players: read the target line twice, then cast.']);
